import React, { useEffect, useState } from 'react';
import Feedback from './Feedback';
import Donate from './Donate';
import Volunteer from './Volunteer';

export default function VolunteerDonorSection({ me = {}, events = [], token, setMsg, activities }) {
  
  const [achievements, setAchievements] = useState(null);
  const [myNgos, setMyNgos] = useState([]);
  const [selectedNgo, setSelectedNgo] = useState(null);

  useEffect(() => {
    if (!token) return;

    fetch((process.env.REACT_APP_API || 'http://localhost:4000') + '/api/actions/achievements', {
      headers: { Authorization: `Bearer ${token}` }
    })
      .then(r => r.json())
      .then(d => setAchievements(d || { badges: [] }))
      .catch(() => setAchievements({ badges: [] }));
  }, [token]);

  async function loadMyNgos() {
    if (!token) { setMsg('Please login'); return; }

    try {
      const res = await fetch((process.env.REACT_APP_API || 'http://localhost:4000') + '/api/actions/my-ngos', {
        headers: { Authorization: `Bearer ${token}` }
      });

      if (!res.ok) throw new Error('Failed to load your NGOs');

      const d = await res.json();
      setMyNgos(d?.ngos || []);
    } catch (err) {
      console.error(err);
      setMsg(err.message || 'Error loading your NGOs');
    }
  }

  async function viewNgoDetails(id) {
    if (!token) { setMsg('Please login'); return; }

    const res = await fetch((process.env.REACT_APP_API || 'http://localhost:4000') + '/api/actions/ngo/' + id, {
      headers: { Authorization: `Bearer ${token}` }
    });

    const d = await res.json();
    setSelectedNgo({
      ngo: d?.ngo || {},
      events: d?.events || [],
      donations: d?.donations || []
    });
  }

  return (
    <div className="panel" style={{ display: 'flex', gap: 16 }}>

      {/* LEFT PANEL */}
      <div style={{ width: 300, flexShrink: 0 }}>
        <h3 style={{ marginBottom: 12 }}>Achievements</h3>

        {/* POINTS CARD */}
        <div
          style={{
            background: "linear-gradient(135deg, #4f46e5, #6366f1)",
            padding: "18px",
            borderRadius: 14,
            color: "#fff",
            textAlign: "center",
            marginBottom: 18,
            boxShadow: "0px 4px 15px rgba(0,0,0,0.15)"
          }}
        >
          <div style={{ fontSize: 42, fontWeight: "bold", lineHeight: 1 }}>
            {me?.points || 0}
          </div>
          <div style={{ opacity: 0.9, letterSpacing: 0.5 }}>POINTS</div>
        </div>

        {/* BADGES */}
        <div>
          <h4 style={{ marginBottom: 8 }}>Badges</h4>

          {!achievements && (
            <div style={{ fontSize: 13, color: "#666" }}>Loading badges...</div>
          )}

          {achievements?.badges?.length === 0 && (
            <div
              style={{
                padding: 14,
                borderRadius: 10,
                background: "#fafafa",
                color: "#777",
                fontSize: 14,
                boxShadow: "0px 3px 10px rgba(0,0,0,0.05)"
              }}
            >
              You have no badges yet.
              <br /> Participate more to earn achievements!
            </div>
          )}

          {achievements?.badges?.length > 0 && (
            <div
              style={{
                display: "grid",
                gridTemplateColumns: "repeat(2, 1fr)",
                gap: 12,
                marginTop: 10
              }}
            >
              {achievements.badges.map((b) => (
                <div
                  key={b.key}
                  style={{
                    background: "#fff",
                    padding: 10,
                    borderRadius: 12,
                    boxShadow: "0px 3px 12px rgba(0,0,0,0.08)",
                    border: "1px solid #eee",
                  }}
                >
                  <div
                    style={{
                      fontWeight: 600,
                      fontSize: 15,
                      marginBottom: 4,
                      color: "#333"
                    }}
                  >
                    {b.title}
                  </div>

                  <div style={{ fontSize: 12, color: "#666", lineHeight: 1.4 }}>
                    {b.desc}
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>

        {/* MY NGOs */}
        <div style={{ marginTop: 20 }}>
          <button
            onClick={loadMyNgos}
            style={{
              width: "100%",
              padding: "10px 14px",
              borderRadius: 10,
              background: "#475569",
              color: "#fff",
              fontWeight: 600,
              border: 0,
              cursor: "pointer",
              boxShadow: "0px 4px 12px rgba(0,0,0,0.15)"
            }}
          >
            My NGOs
          </button>

          <div style={{ marginTop: 10 }}>
            {myNgos.map((n) => (
              <div
                key={n.id}
                style={{
                  display: "flex",
                  justifyContent: "space-between",
                  alignItems: "center",
                  padding: 10,
                  background: "#fff",
                  borderRadius: 12,
                  border: "1px solid #eee",
                  marginBottom: 10,
                  boxShadow: "0px 3px 10px rgba(0,0,0,0.05)"
                }}
              >
                <div>
                  <strong>{n.name}</strong>
                  <div style={{ fontSize: 12, color: "#666" }}>{n.email}</div>
                </div>

                <button
                  onClick={() => viewNgoDetails(n.id)}
                  style={{
                    padding: "6px 10px",
                    borderRadius: 8,
                    background: "#2563eb",
                    color: "#fff",
                    border: "none",
                    cursor: "pointer",
                    fontSize: 12
                  }}
                >
                  View
                </button>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* MIDDLE PANEL */}
      <div style={{ flex: 1 }}>
        <h3>Recognition & Actions</h3>
        <p>
          <strong>Name:</strong> {me?.name || "Unknown"} — <strong>Level:</strong>{" "}
          {me?.points >= 200
            ? "Gold"
            : me?.points >= 100
            ? "Silver"
            : me?.points >= 50
            ? "Bronze"
            : me?.points >= 10
            ? "Member"
            : "New"}
        </p>

        <div style={{
          background: '#fff', padding: 12,
          borderRadius: 8,
          boxShadow: '0 8px 24px rgba(2,6,23,0.04)'
        }}>
          <h4>Give Feedback</h4>
          <Feedback token={token} setMsg={setMsg} />

          <h4 style={{ marginTop: 12 }}>Donate</h4>
          <Donate token={token} setMsg={setMsg} />

          <h4 style={{ marginTop: 12 }}>Volunteer for Event</h4>
          <Volunteer token={token} events={events} setMsg={setMsg} />
        </div>
      </div>

      {/* RIGHT PANEL */}
      <div style={{ width: 340, flexShrink: 0 }}>
        <h4>Details</h4>

        {selectedNgo ? (
          <div style={{ background: '#fff', padding: 12, borderRadius: 10 }}>
            <h5>{selectedNgo?.ngo?.name || "Unknown NGO"}</h5>
            <div style={{ fontSize: 13, color: '#666' }}>
              {selectedNgo?.ngo?.email || "No email available"}
            </div>

            <div style={{ marginTop: 10 }}>
              <strong>Events</strong>
              {selectedNgo?.events?.length > 0 ? (
                selectedNgo.events.map(ev => (
                  <div key={ev.id} style={{ padding: 8, borderBottom: '1px solid #f0f0f0' }}>
                    {ev.title}
                  </div>
                ))
              ) : (
                <div>No events yet.</div>
              )}
            </div>

            <div style={{ marginTop: 10 }}>
              <strong>Recent Donations</strong>
              {selectedNgo?.donations?.length > 0 ? (
                selectedNgo.donations.slice(0, 6).map(d => (
                  <div key={d.id} style={{ padding: 6 }}>
                    {d.donor_name} — ₹{d.amount}
                  </div>
                ))
              ) : (
                <div>No donations yet.</div>
              )}
            </div>
          </div>
        ) : (
          <div style={{ background: '#fff', padding: 12, borderRadius: 10 }}>
            Select an NGO to see details.
          </div>
        )}
      </div>

    </div>
  );
}
